const topic = ($json.chatInput || '').trim();

if (!topic) {
  throw new Error('Chủ đề không được để trống. Vui lòng nhập lại.');
}

return [{
  json: {
    candidate_topic: topic,
    attempt: 0,
    max_attempts: 5
  }
}];

const rows = $input.all();
const existingTopics = rows.map(r => r.json.topic).filter(Boolean);
const init = $('Code: Init chủ đề').first().json;

return [{
  json: {
    candidate_topic: init.candidate_topic,
    attempt: init.attempt,
    max_attempts: init.max_attempts,
    existing_topics: existingTopics
  }
}];

function normalize(str) {
  return (str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, '')
    .trim();
}

const data = $input.first().json;
const normCandidate = normalize(data.candidate_topic);

const isDuplicate = (data.existing_topics || []).some(t => {
  const nt = normalize(t);
  if (!nt || !normCandidate) return false;
  return nt === normCandidate || nt.includes(normCandidate) || normCandidate.includes(nt);
});

return [{
  json: {
    ...data,
    is_duplicate: isDuplicate
  }
}];

return [{
  json: {
    text: `Đã thử ${$json.attempt} lần nhưng chưa tìm được chủ đề mới không trùng lặp cho \"${$json.candidate_topic}\". Bạn vui lòng nhập một chủ đề khác nhé.`
  }
}];

