let inputItem = $input.first().json;
let raw = '';

if (inputItem.content && inputItem.content.parts) {
  raw = inputItem.content.parts[0].text;
} else if (inputItem.text) {
  raw = inputItem.text;
} else if (typeof inputItem === 'string') {
  raw = inputItem;
} else {
  raw = JSON.stringify(inputItem);
}

let cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('AI trả JSON đề xuất chủ đề không hợp lệ: ' + e.message);
}

const prev = $('Code: Kiểm tra trùng chủ đề').first().json;

return [{
  json: {
    candidate_topic: parsed.new_topic || prev.candidate_topic,
    attempt: prev.attempt,
    max_attempts: prev.max_attempts,
    existing_topics: prev.existing_topics
  }
}];

const resp = $input.first().json;
const results = resp.results || [];

const formatted = results.map((r, i) =>
  `[Nguồn ${i + 1}] ${r.title}\nURL: ${r.url}\nNgày: ${r.published_date || 'không rõ'}\nTóm tắt: ${r.content}\n`
).join('\n---\n');

const topic = $('Code: Kiểm tra trùng chủ đề').first().json.candidate_topic;

return [{
  json: {
    topic: topic,
    search_answer: resp.answer || '',
    search_results_text: formatted || 'Không tìm thấy kết quả tìm kiếm.',
    raw_sources: results.map(r => ({ title: r.title, url: r.url, published_date: r.published_date || null }))
  }
}];

